// Exercise cudf::distance with valid iterators over the same sequence.
// Build a small vector and choose two iterator positions within [begin, end].
unsigned int n_raw = *FUZZ_PARAM(unsigned int);
std::size_t n = static_cast<std::size_t>(n_raw % 256u);  // keep allocations small
std::vector<int> v(n);

// Valid iterator positions in [0, n] (end allowed)
std::size_t i = static_cast<std::size_t>(*FUZZ_PARAM(unsigned int)) % (n + 1);
std::size_t j = static_cast<std::size_t>(*FUZZ_PARAM(unsigned int)) % (n + 1);

auto f = v.begin();
auto it_f = f + static_cast<std::ptrdiff_t>(i);
auto it_l = f + static_cast<std::ptrdiff_t>(j);

// Invoke target and validate against std::distance cast to cudf::size_type.
cudf::size_type got = cudf::distance(it_f, it_l);
cudf::size_type exp = static_cast<cudf::size_type>(std::distance(it_f, it_l));
FUZZ_ASSERT(got == exp, "cudf::distance must match std::distance cast to cudf::size_type");

// Validation: Iterators are from the same container and within range; property checked via equality to std::distance.

// Compare two valid cudf::data_type instances.
bool eq = (*lhs == *rhs);

// Basic properties: reflexivity and symmetry with operator==
FUZZ_ASSERT((*lhs == *lhs), "data_type equality must be reflexive");
FUZZ_ASSERT(eq == (*rhs == *lhs), "data_type equality must be symmetric");

// No ownership changes; return both inputs to the pool.
// Validation: Uses only const accessors; inputs are preserved and returned.

// Exercise inequality and ensure it is logical negation of equality.
bool ne = (*lhs != *rhs);
bool eq = (*lhs == *rhs);
FUZZ_ASSERT(ne == !eq, "operator!= must be the logical negation of operator==");
FUZZ_ASSERT(!(*lhs != *lhs), "data_type inequality must be false for identical object");

// No ownership changes; return both inputs to the pool.
// Validation: Confirms != and == complementarity; inputs are preserved.

// Construct a cudf::data_type instance in various valid ways to maximize coverage.
// Modes: 0 = default ctor, 1 = id-only ctor, 2 = decimal id + scale ctor.
unsigned int mode = *FUZZ_PARAM(unsigned int) % 3u;

// Choose a random type_id uniformly from the enum domain.
int num_ids = static_cast<int>(cudf::type_id::NUM_TYPE_IDS);
int raw_idx = static_cast<int>(*FUZZ_PARAM(unsigned int));
int idx = (num_ids > 0) ? (raw_idx % num_ids) : 0;
cudf::type_id chosen_id = static_cast<cudf::type_id>(idx);

// For decimal constructor path, select one of the decimal IDs and a reasonable scale.
int dec_pick = static_cast<int>(*FUZZ_PARAM(unsigned int)) % 3;
cudf::type_id decimal_id = (dec_pick == 0) ? cudf::type_id::DECIMAL32
                          : (dec_pick == 1) ? cudf::type_id::DECIMAL64
                                            : cudf::type_id::DECIMAL128;
int32_t scale = *FUZZ_PARAM(int32_t);
// Constrain scale to a typical fixed-point range to avoid pathological values.
scale = static_cast<int32_t>(scale % 39); // [0, 38]
scale -= 19; // [-19, 19]

// Define the output pointer and allocate according to the selected mode.
cudf::data_type *out = nullptr;

// The (id, scale) ctor must only be used with a DECIMAL* id; enforce explicitly by construction.
if (mode == 0u) {
  // Default constructs to EMPTY with scale 0.
  out = new cudf::data_type();
} else if (mode == 1u) {
  // Any enum value is valid for the id-only constructor.
  out = new cudf::data_type(chosen_id);
} else {
  // Decimal path: ensure a decimal id is used with the scale constructor.
  out = new cudf::data_type(decimal_id, scale);
}

// Validation: Ensure output is non-null and reflects constructor invariants.
FUZZ_ASSERT(out != nullptr, "Allocation for cudf::data_type must succeed");

// Attribute tracking for downstream stubs (e.g., size_of constraints and equality behavior).
int id_as_int = static_cast<int>(out->id());
FUZZ_SET_ATTR_INT(out, "type_id", id_as_int);
FUZZ_SET_ATTR_INT(out, "scale", out->scale());

// Flag whether this logical type is decimal.
bool is_decimal = (out->id() == cudf::type_id::DECIMAL32) ||
                  (out->id() == cudf::type_id::DECIMAL64) ||
                  (out->id() == cudf::type_id::DECIMAL128);
FUZZ_SET_ATTR_INT(out, "is_decimal", is_decimal ? 1 : 0);

// Flag whether this is a fixed-width type for size_of; mark non-fixed for {STRING, LIST, STRUCT, DICTIONARY32}.
bool is_non_fixed = (out->id() == cudf::type_id::STRING) ||
                    (out->id() == cudf::type_id::LIST) ||
                    (out->id() == cudf::type_id::STRUCT) ||
                    (out->id() == cudf::type_id::DICTIONARY32);
FUZZ_SET_ATTR_INT(out, "is_fixed_width", is_non_fixed ? 0 : 1);

// Summary validation: Output is initialized, attributes recorded for downstream use (e.g., cudf::size_of).
